57	  it.todo("writes {premium} for a quote step and {payout, remainingCap} for a claim step");
58	  it.todo("exits with a non-zero status and writes to stderr on an unknown item type");
59	  it.todo("exits with a non-zero status and writes to stderr on an invalid claim");
